SELECT ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=6 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=6),0),2), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=12 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=12),0),2), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=18 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=18),0),2), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=24 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=24),0),2) FROM loan_monthly_snapshot s JOIN loan l USING (loan_id) WHERE l.purpose='Equity Release / Top-up' AND l.origination_date >= DATE '2022-01-01' AND l.origination_date < DATE '2023-01-01' AND s.loan_status<>'Closed'
